// Explicit request for function inlining (compiler hint)
// Best used for small, frequently called functions
inline int fast_increment(int x) {
    return x + 1;
}

int calculate_sequence(int start) {
    // Compiler attempts replacement: return (start + 1);
    int step1 = fast_increment(start);

    // Benefit: Eliminates function call overhead
    return fast_increment(step1);
}

// Note: Functions defined inside class bodies are
// also implicit candidates for inlining.
class State {
    int value;
public:
    int get_val() const { return value; }
};
